CREATE FUNCTION public.campus_set_audit_timestamps() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.i_ts := OLD.i_ts;
  NEW.crte_usr_id := OLD.crte_usr_id;
  NEW.u_ts := CURRENT_TIMESTAMP;
  IF NEW.a_in = 0 AND OLD.a_in = 1 THEN
    NEW.d_ts := CURRENT_TIMESTAMP;
  ELSIF NEW.a_in = 1 THEN
    NEW.d_ts := NULL;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.campus_sync_user_role() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.role_id IS DISTINCT FROM OLD.role_id AND NEW.role IS NOT DISTINCT FROM OLD.role THEN
      SELECT role_code INTO NEW.role FROM role_t WHERE role_id = NEW.role_id;
    END IF;
  END IF;
  SELECT role_id INTO NEW.role_id FROM role_t WHERE role_code = NEW.role;
  RETURN NEW;
END;
$$;

COMMIT;
